findings.remediationCode:
# 1. Create IAM role instead of embedding credentials
resource "aws_iam_instance_profile" "app" {
  name = "app-instance-profile"
  role = aws_iam_role.app.name
}

resource "aws_instance" "app" {
  # Remove user_data credentials block entirely
  iam_instance_profile = aws_iam_instance_profile.app.name
  metadata_options {
    http_tokens = "required"  # Also fix HALL-005
  }
}

resource "aws_eks_cluster" "main" {
  name = var.cluster_name

  vpc_config {
    # Option A: Fully private (recommended)
    endpoint_public_access  = false
    endpoint_private_access = true

    # Option B: Restrict to known IPs
    # endpoint_public_access       = true
    # public_access_cidrs          = ["203.0.113.0/24"]  # Your corporate IPs
  }
}

findings.poc:
Target: es.tf (AWS)
Check: AVD-AWS-0046 — Elasticsearch doesn't enforce HTTPS traffic.

Resource: aws_elasticsearch_domain
  domain_endpoint_options {
    enforce_https = false    ← VIOLATION
  }

findings.remediationCode:
resource "aws_elasticsearch_domain" "main" {
  domain_endpoint_options {
    enforce_https       = true           # Fix: was false
    tls_security_policy = "Policy-Min-TLS-1-2-2019-07"
  }

  encrypt_at_rest {
    enabled = true
  }

  node_to_node_encryption {
    enabled = true
  }
}

resource "aws_instance" "app" {
  ami           = var.ami_id
  instance_type = "t3.micro"

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"   # Fix: was "optional"
    http_put_response_hop_limit = 1            # Prevent SSRF hop
  }
}

resource "aws_db_instance" "main" {
  storage_encrypted = true                      # Fix: was false
  kms_key_id        = aws_kms_key.rds.arn       # Use dedicated KMS key

  # Note: requires recreation of existing unencrypted instances
  # Plan migration window before applying
}

resource "aws_kms_key" "rds" {
  description             = "RDS encryption key"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_db_instance" "main" {
  publicly_accessible = false   # Fix: was true

  # Ensure placed in private subnet group
  db_subnet_group_name = aws_db_subnet_group.private.name

  # Restrict security group to application tier only
  vpc_security_group_ids = [aws_security_group.rds_private.id]
}

resource "aws_db_subnet_group" "private" {
  name       = "rds-private"
  subnet_ids = var.private_subnet_ids  # Private subnets only
}

findings.poc:
Target: db-app.tf (AWS)
Check: AVD-AWS-0345 — Disallow unrestricted S3 IAM Policies

Resource: aws_iam_role_policy
  policy = jsonencode({
    Statement = [{
      Action   = ["s3:*"]          ← VIOLATION
      Resource = ["*"]             ← VIOLATION
      Effect   = "Allow"
    }]
  })

findings.remediationCode:
resource "aws_iam_role_policy" "app_s3" {
  name = "app-s3-restricted"
  role = aws_iam_role.app.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        # Fix: Replace s3:* with specific actions
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        # Fix: Replace * with specific bucket ARN
        Resource = [
          "${aws_s3_bucket.app.arn}/*"
        ]
        Effect = "Allow"
      }
    ]
  })
}

resource "aws_ebs_volume" "data" {
  availability_zone = var.az
  size              = 20
  encrypted         = true                    # Fix: was false
  kms_key_id        = aws_kms_key.ebs.arn
}

# Enable account-level default encryption (preventive control)
resource "aws_ebs_encryption_by_default" "default" {
  enabled = true
}

resource "azurerm_app_service" "main" {
  site_config {
    min_tls_version = "1.2"  # Fix: was "1.1" — BROKEN_NOW
    # Optionally enforce TLS 1.3 where clients support it:
    # min_tls_version = "1.3"
  }
}

